rows = list(csv.DictReader(open(os.path.join(HERE, "out", "audit_candidates.csv"))))
with open(os.path.join(HERE, "sample_audit.csv"), "w", newline="") as fo:
    w = csv.writer(fo)
    w.writerow(["idx", "agent", "pr_url", "file", "detection_method", "path_rule", "header_status_from_patch", "additions", "deletions", "pr_files", "merged",
                "truly_generated", "judgment", "overwritten_by_regeneration", "rationale"])
    for i, r in enumerate(rows, 1):
        g, j, o, why = J[i]
        w.writerow([i, r["agent"], r["html_url"], r["file"], r["method"], r["path_rule"], r["hdr_status_patch"], r["add"], r["dele"], r["n_pr_files"], r["merged"], g, j, o, why])
import collections
